func(s *Service)metrics(w http.ResponseWriter,_ *http.Request){if s.Metrics==nil{writeJSON(w,200,map[string]int{});return};writeJSON(w,200,s.Metrics.Snapshot())}
func(s *Service)HandleAgentResult(ctx context.Context,hostID string,res agent.CommandResult)error{
	wk,err:=s.Store.GetWorker(ctx,res.WorkerID)
	if err!=nil{return err}
	now:=time.Now().UTC()
	wk.UpdatedAt=now
	if !res.OK{
		wk.State=core.WorkerFailed
		wk.FailureReason=truncate(res.SafeError)
		wk.FailedAt=now
		_=s.Store.AppendAudit(ctx,core.AuditEvent{Actor:"agent:"+hostID,Action:"command_result",ResourceType:"worker",ResourceID:wk.ID,Result:"error",SafeDetail:wk.FailureReason})
		if err:=s.Store.UpsertWorker(ctx,wk);err!=nil{return err}
		return s.enqueueTerminalCleanup(ctx,&wk)
	}
	if res.Handle!=nil{
		wk.ProviderHandle=res.Handle.ProviderID
		if core.CanTransitionWorker(wk.State,core.WorkerStarting){wk.State=core.WorkerStarting}
		if core.CanTransitionWorker(wk.State,core.WorkerRegistering){wk.State=core.WorkerRegistering}
		if wk.State==core.WorkerRegistering&&wk.RegistrationStartedAt.IsZero(){wk.RegistrationStartedAt=now}
	}
	terminal:=false
	if res.State!=nil{
		terminalSample:=res.State.State==core.WorkerCompleted||res.State.State==core.WorkerFailed
		recordWorkerUsage(&wk,res.State.Usage,now,(wk.State==core.WorkerBusy&&wk.CompletedAt.IsZero())||(terminalSample&&!wk.StartedAt.IsZero()))
		preJob:=wk.StartedAt.IsZero()&&wk.State!=core.WorkerBusy&&wk.State!=core.WorkerCompleted
		wk.ProviderExitCode=res.State.ExitCode
		wk.ProviderOOMKilled=res.State.OOMKilled
		if preJob&&strings.TrimSpace(res.State.Diagnostics)!=""{wk.ProviderDiagnostics=res.State.Diagnostics}
		switch res.State.State{
		case core.WorkerCompleted:
			if core.CanTransitionWorker(wk.State,core.WorkerCompleted){wk.State=core.WorkerCompleted;if wk.CompletedAt.IsZero(){wk.CompletedAt=now}}else if wk.State!=core.WorkerCompleted{wk.State=core.WorkerFailed;wk.FailureReason="provider exited before worker reached a runnable state";wk.FailedAt=now}
			terminal=true
		case core.WorkerFailed:
			wk.State=core.WorkerFailed
			wk.FailureReason=truncate(res.State.SafeDetail)
			wk.FailedAt=now
			if res.State.ExitCode!=nil{wk.FailureReason=truncate(fmt.Sprintf("%s (exit code %d)",wk.FailureReason,*res.State.ExitCode))}
			terminal=true
		case core.WorkerDeleted:
			if wk.State==core.WorkerCleanupPending||wk.State==core.WorkerDeleting{wk.State=core.WorkerDeleted;wk.ProviderHandle=""}else{wk.State=core.WorkerFailed;wk.FailureReason="provider worker disappeared before cleanup";wk.FailedAt=now;terminal=true}
		}
	}
	if res.Handle==nil&&res.State==nil&&wk.State==core.WorkerCleanupPending{wk.State=core.WorkerDeleted;wk.ProviderHandle=""}
	if err:=s.Store.UpsertWorker(ctx,wk);err!=nil{return err}
	if terminal{_ = s.maybeAutoTunePool(ctx,wk.PoolID);return s.enqueueTerminalCleanup(ctx,&wk)}
	return nil
}
func recordWorkerUsage(wk *core.Worker,usage *provider.WorkerUsage,at time.Time,countSample bool){
	if wk==nil||usage==nil{return}
	cpu:=usage.CPUMillis;if cpu<0{cpu=0}
	memory:=usage.MemoryBytes;if memory<0{memory=0}
	wk.Usage.CurrentCPUMillis=cpu
	wk.Usage.CurrentMemoryBytes=memory
	wk.Usage.UpdatedAt=at
	if !countSample{return}
	n:=wk.Usage.Samples
	wk.Usage.AverageCPUMillis=rollingAverage(wk.Usage.AverageCPUMillis,cpu,n)
	wk.Usage.AverageMemoryBytes=rollingAverage(wk.Usage.AverageMemoryBytes,memory,n)
	if cpu>wk.Usage.PeakCPUMillis{wk.Usage.PeakCPUMillis=cpu}
	if memory>wk.Usage.PeakMemoryBytes{wk.Usage.PeakMemoryBytes=memory}
	if n<^uint64(0){wk.Usage.Samples=n+1}
}
func(s *Service)maybeAutoTunePool(ctx context.Context,poolID string)error{
	p,err:=s.Store.GetPool(ctx,poolID);if err!=nil{return err}
	if !p.AutoTuneResources{return nil}
	workers,err:=s.Store.ListWorkers(ctx);if err!=nil{return err}
	rec:=telemetry.RecommendResources(p,workers)
	if !rec.Ready{return nil}
	if rec.Recommended.CPUMillis==p.Resources.CPUMillis&&rec.Recommended.MemoryBytes==p.Resources.MemoryBytes{return nil}
	candidate:=p
	candidate.Resources.CPUMillis=rec.Recommended.CPUMillis
	candidate.Resources.MemoryBytes=rec.Recommended.MemoryBytes
	hosts,err:=s.Store.ListHosts(ctx);if err!=nil{return err}
	fits:=false
	for _,host:=range hosts{if scheduler.HostRejectionReason(host,candidate,core.Resources{})==""{fits=true;break}}
	if !fits{
		_=s.Store.AppendAudit(ctx,core.AuditEvent{Actor:"auto-tuner",Action:"auto_tune_resources",ResourceType:"pool",ResourceID:p.ID,Result:"skipped",SafeDetail:"recommended CPU/RAM does not fit any compatible empty host"})
		return nil
	}
	if err:=core.ValidateRunnerPool(candidate);err!=nil{return err}
	if err:=s.Policy.ValidatePool(candidate);err!=nil{return err}
	oldCPU,oldMemory:=p.Resources.CPUMillis,p.Resources.MemoryBytes
	if err:=s.Store.UpsertPool(ctx,candidate);err!=nil{return err}
	_=s.Store.AppendAudit(ctx,core.AuditEvent{Actor:"auto-tuner",Action:"auto_tune_resources",ResourceType:"pool",ResourceID:p.ID,Result:"ok",SafeDetail:fmt.Sprintf("cpu=%dm->%dm memory=%d->%d jobs=%d confidence=%s",oldCPU,candidate.Resources.CPUMillis,oldMemory,candidate.Resources.MemoryBytes,rec.Jobs,rec.Confidence)})
	return nil
}
func(s *Service)enqueueTerminalCleanup(ctx context.Context,wk *core.Worker)error{
	if wk==nil||strings.TrimSpace(wk.ProviderHandle)==""||s.Hub==nil{return nil}
	if wk.State!=core.WorkerCleanupPending{
		if !core.CanTransitionWorker(wk.State,core.WorkerCleanupPending){return nil}
		wk.State=core.WorkerCleanupPending
		wk.UpdatedAt=time.Now().UTC()
		if err:=s.Store.UpsertWorker(ctx,*wk);err!=nil{return err}
	}
	h:=provider.WorkerHandle{ProviderID:wk.ProviderHandle,HostID:wk.HostID}
	if err:=s.Hub.Enqueue(wk.HostID,agent.Command{Type:agent.CommandDelete,WorkerID:wk.ID,Provider:wk.ProviderID,Handle:&h});err!=nil{return err}
	_=s.Store.AppendAudit(ctx,core.AuditEvent{Actor:"control",Action:"cleanup_worker",ResourceType:"worker",ResourceID:wk.ID,Result:"queued",SafeDetail:wk.FailureReason})
	return nil
}
func(s *Service)inspectSecurity(ctx context.Context,p core.RunnerPool)(githubrunner.PoolSecurityPosture,error){if s.Catalog==nil{return githubrunner.PoolSecurityPosture{},errors.New("github catalog is not configured")};return githubrunner.InspectPoolSecurity(ctx,s.Catalog,p)}
func(s *Service)requireSafeSecurity(ctx context.Context,p core.RunnerPool)(githubrunner.PoolSecurityPosture,error){posture,err:=s.inspectSecurity(ctx,p);if err!=nil{return posture,err};if !posture.Safe{return posture,errors.New(strings.Join(posture.Reasons,"; "))};return posture,nil}
func decode(w http.ResponseWriter,r *http.Request,v any)bool{defer r.Body.Close();d:=json.NewDecoder(io.LimitReader(r.Body,1<<20));d.DisallowUnknownFields();if err:=d.Decode(v);err!=nil{problem(w,400,err);return false};var extra any;if err:=d.Decode(&extra);err!=io.EOF{if err==nil{err=errors.New("request body must contain exactly one JSON value")};problem(w,400,err);return false};return true}
func writeJSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_=json.NewEncoder(w).Encode(v)}
func problem(w http.ResponseWriter,status int,err error){writeJSON(w,status,map[string]any{"error":http.StatusText(status),"detail":truncate(err.Error())})}
func bearer(r *http.Request)string{v:=r.Header.Get("Authorization");if strings.HasPrefix(v,"Bearer "){return strings.TrimSpace(strings.TrimPrefix(v,"Bearer "))};return ""}
func randomID()string{b:=make([]byte,8);_,_=rand.Read(b);return base64.RawURLEncoding.EncodeToString(b)}
func truncate(v string)string{if len(v)>512{return v[:512]};return v}
func actor(ctx context.Context)string{p:=auth.PrincipalFrom(ctx);if p.Name!=""{return p.Name};return "api"}
func firstNonEmpty(a,b string)string{if strings.TrimSpace(a)!=""{return a};return b}
func securityHeaders(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("X-Frame-Options","DENY");w.Header().Set("Referrer-Policy","no-referrer");w.Header().Set("Content-Security-Policy","default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'");if r.TLS!=nil{w.Header().Set("Strict-Transport-Security","max-age=31536000")};next.ServeHTTP(w,r)})}
